        .grid-container {
            display: grid;
            grid-template-columns: auto auto auto;
            background-color: rgb(55, 55, 55);
            padding: 2px;
        }

        .grid-item {
            background-color: rgb(242, 242, 242);
            border: 1px solid rgba(0, 0, 0, 0.8);
            padding: 12px;
            font-size: 30px;
            text-align: center;
        }

        .page-thumb {
            width: 100px;
            border-radius: .5em;
            border: 5px solid rgb(242, 242, 242);
            background-color: rgb(242, 242, 242);
            transition: all 0.3s ease 0s;
            box-shadow: rgba(0, 0, 0, 0.25) 3px 4px 5px;
        }

        .page-thumb:hover {
            transition: all 0.3s ease 0s;
            transform: scale(1.04);
        }

        h2 {
            font-family: &quot;Lora&quot;, Palatino, Georgia, Times, serif;
            font-style: italic;
            font-size: 2.0em;
            margin-bottom: 5px;
        }

        @media only screen and (max-width: 500px) {
            .grid-container {
                display: flow-root;
                padding: 2px;
                text-align: center;
            }
            .page-thumb {
